import java.io.*;
import java.util.*;

public class gfg {
    static Map<String, Boolean> memo = new HashMap<>();

    static boolean solve(long w, long m) {
        if (w <= 3 || m == 1) {
            return true;
        }
        String key = w + "," + m;
        Boolean cached = memo.get(key);
        if (cached != null) {
            return cached;
        }
        boolean result = trySolve(w, m - 1) || trySolve(w, m) || trySolve(w, m + 1);
        memo.put(key, result);
        return result;
    }

    static boolean trySolve(long w, long m) {
        return m % w == 0 && solve(w, m / w);
    }

    public static void main(String[] args) {
        PrintWriter out = new PrintWriter(System.out);
        FastReader sc = new FastReader();
        long w = sc.nextLong();
        long m = sc.nextLong();
        out.println(solve(w, m) ? "YES" : "NO");
        out.flush();
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        long nextLong() {
            return Long.parseLong(next());
        }
    }
}
